args <- commandArgs(trailingOnly = TRUE)
value <- function(key) {
  i <- which(args == key)
  if (length(i) != 1L || i == length(args) || startsWith(args[i + 1L], "--")) stop("Required: ", key)
  args[i + 1L]
}
if ("--help" %in% args) {
  cat("Usage: Rscript plot_asc_like_candidate_evidence.R --input ANNOTATED.rds --annotation-map MAPPING.csv --out NEW_OUTPUT [--preflight]\n")
  quit(status = 0L)
}
input_arg <- normalizePath(value("--input"), winslash = "/", mustWork = TRUE)
map_arg <- normalizePath(value("--annotation-map"), winslash = "/", mustWork = TRUE)
root <- normalizePath(value("--out"), winslash = "/", mustWork = FALSE)
if (dir.exists(root) && length(list.files(root, all.files = TRUE, no.. = TRUE))) stop("Use a new or empty output directory")
if (tolower(root) %in% tolower(c(dirname(input_arg), dirname(map_arg)))) stop("Keep output separate from inputs")
required <- c("Seurat", "SeuratObject", "Matrix", "ggplot2", "patchwork", "dplyr", "scales", "digest", "yaml")
missing <- required[!vapply(required, requireNamespace, logical(1), quietly = TRUE)]
if (length(missing)) stop("Install dependencies separately: ", paste(missing, collapse = ", "))
if ("--preflight" %in% args) {
  message("Preflight PASS: input paths and dependencies checked; object metadata checked only during execution")
  quit(status = 0L)
}
